@import "tailwindcss";

@theme {
  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));
  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));
  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));
  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));
  --radius-lg: var(--radius);
  --radius-md: calc(var(--radius) - 2px);
  --radius-sm: calc(var(--radius) - 4px);

  --font-display: 'Nunito', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}

@layer base {
  :root {
    --background: 52 100% 97%;
    --foreground: 150 30% 15%;
    --card: 0 0% 100%;
    --card-foreground: 150 30% 15%;
    --popover: 0 0% 100%;
    --popover-foreground: 150 30% 15%;
    --primary: 153 42% 30%;
    --primary-foreground: 52 100% 97%;
    --secondary: 30 88% 67%;
    --secondary-foreground: 150 30% 15%;
    --muted: 40 30% 90%;
    --muted-foreground: 150 10% 40%;
    --accent: 30 88% 67%;
    --accent-foreground: 150 30% 15%;
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 0 0% 98%;
    --border: 40 20% 85%;
    --input: 40 20% 85%;
    --ring: 153 42% 30%;
    --radius: 0.75rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-body);
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
  }
}

/* Custom scrollbar for carousel */
.carousel-scroll::-webkit-scrollbar {
  display: none;
}
.carousel-scroll {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Grain texture overlay */
.grain::before {
  content: '';
  position: fixed;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E") repeat;
  opacity: 0.025;
  pointer-events: none;
  z-index: 9999;
}

import { useState } from "react"
import { Menu, X, ShoppingBasket } from "lucide-react"

const navLinks = [
  { label: "Products", href: "#products" },
  { label: "Our Stores", href: "#stores" },
  { label: "Recipes", href: "#recipes" },
  { label: "About Us", href: "#about" },
]

export default function Header() {
  const [open, setOpen] = useState(false)

  return (
    <header className="sticky top-0 z-50 bg-[#FEFAE0]/90 backdrop-blur-md border-b border-[#2D6A4F]/10">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <a href="#" className="flex items-center gap-2 text-[#2D6A4F]">
            <ShoppingBasket className="w-7 h-7" />
            <span className="font-extrabold text-xl tracking-tight" style={{ fontFamily: "var(--font-display)" }}>
              Fresh Pantry
            </span>
          </a>

          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <a
                key={link.label}
                href={link.href}
                className="text-sm font-semibold text-[#2D6A4F]/80 hover:text-[#2D6A4F] transition-colors"
              >
                {link.label}
              </a>
            ))}
          </nav>

          <button
            className="md:hidden p-2 text-[#2D6A4F]"
            onClick={() => setOpen(!open)}
            aria-label="Toggle menu"
          >
            {open ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      <div
        className={`md:hidden transition-all duration-300 overflow-hidden ${
          open ? "max-h-64 opacity-100" : "max-h-0 opacity-0"
        }`}
      >
        <div className="px-4 pb-4 space-y-2 border-t border-[#2D6A4F]/10">
          {navLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              onClick={() => setOpen(false)}
              className="block py-2 text-sm font-semibold text-[#2D6A4F]/80 hover:text-[#2D6A4F]"
            >
              {link.label}
            </a>
          ))}
        </div>
      </div>
    </header>
  )
}

