export default function Categories() {
  const [hovered, setHovered] = useState<string | null>(null)

  return (
    <section className="py-16 md:py-24">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2
