                onMouseEnter={() => setHovered(cat.name)}
                onMouseLeave={() => setHovered(null)}
              >
                <img
                  src={cat.image}
                  alt={cat.name}
                  className={`absolute inset-0 w-full h-full object-cover transition-transform duration-500 ${
                    isHovered ? "scale-110" : "scale-100"
                  }`}
                  loading="lazy"
                />
                <div
                  className={`absolute inset-0 bg-gradient-to-t from-[#2D6A4F]/90 via-[#2D6A4F]/30 to-transparent transition-opacity duration-300 ${
                    isHovered ? "opacity-100" : "opacity-70"
                  }`}
                />
                <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6">
                  <div
                    className={`w-12 h-12 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center mb-3 transition-all duration-300 ${
                      isHovered ? "scale-110 bg-white/30" : ""
                    }`}
                  >
                    <Icon className="w-6 h-6 text-white" />
                  </div>
                  <h3
                    className={`text-xl font-black text-white mb-1 transition-transform duration-300 ${
                      isHovered ? "translate-y-0" : ""
                    }`}
                    style={{ fontFamily: "var(--font-display)" }}
                  >
                    {cat.name}
                  </h3>
                  <p
                    className={`text-sm text-white/80 max-w-xs transition-all duration-300 ${
                      isHovered ? "opacity-100 translate-y-0" : "opacity-0 translate-y-2"
