        <p className="text-[#2D6A4F]/60 text-sm md:text-base mb-8 max-w-lg mx-auto">
          Enter your zip code to discover the nearest store, hours, and
          directions.
        </p>

        <div className="flex flex-col sm:flex-row items-center gap-3 max-w-md mx-auto mb-8">
          <input
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            placeholder="Enter your zip code"
            value={zip}
            onChange={(e) => setZip(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSearch()}
            className="w-full sm:flex-1 px-5 py-3 rounded-full border-2 border-[#2D6A4F]/15 bg-white text-[#2D6A4F] placeholder:text-[#2D6A4F]/40 text-sm font-medium focus:outline-none focus:border-[#2D6A4F]/40 transition-colors"
          />
          <button
            onClick={handleSearch}
            className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-6 py-3 rounded-full bg-[#2D6A4F] text-white font-bold text-sm hover:bg-[#245c43] transition-colors shadow-lg shadow-[#2D6A4F]/20"
          >
            <Search className="w-4 h-4" />
            Search
          </button>
        </div>

        {searched && results && results.length > 0 && (
          <div className="text-left space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {results.map((store) => (
              <div
                key={store.name}
                className="bg-white rounded-2xl p-5 border border-[#2D6A4F]/5 shadow-sm hover:shadow-md transition-shadow"
              >
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                  <div className="flex-1">
                    <h3 className="font-bold text-[#2D6A4F] text-sm mb-1">
                      {store.name}
                    </h3>
                    <p className="text-xs text-[#2D6A4F]/60 mb-2">
                      {store.address}
                    </p>
                    <div className="flex items-center gap-4 text-xs text-[#2D6A4F]/70">
                      <span className="inline-flex items-center gap-1">
                        <Clock className="w-3.5 h-3.5" />
                        {store.hours}
                      </span>
                      <span className="inline-flex items-center gap-1 font-semibold text-[#F4A261]">
                        <Navigation className="w-3.5 h-3.5" />
                        {store.distance}
                      </span>
                    </div>
                  </div>
                  <button className="self-start sm:self-center px-4 py-2 rounded-full bg-[#F4A261]/10 text-[#F4A261] text-xs font-bold hover:bg-[#F4A261]/20 transition-colors">
                    Get Directions
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {searched && results && results.length === 0 && (
          <p className="text-sm text-[#2D6A4F]/60">
            Please enter a valid zip code to find stores near you.
          </p>
        )}
      </div>
    </section>
  )
}

