              Fresh Pantry
            </span>
          </a>

          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <a
                key={link.label}
                href={link.href}
                className="text-sm font-semibold text-[#2D6A4F]/80 hover:text-[#2D6A4F] transition-colors"
              >
                {link.label}
