import { useState } from "react"
import { Search, MapPin, Clock, Phone } from "lucide-react"

const mockStores = [
  {
    name: "Fresh Pantry — Downtown",
    address: "142 Market Street, Downtown",
    hours: "7:00 AM – 10:00 PM",
    phone: "(555) 123-4567",
  },
