from html.parser import HTMLParser

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
        self.has_script = False
        self.has_style = False

    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        if tag == 'script':
            attrs_dict = dict(attrs)
            if attrs_dict.get('type') == 'module':
                self.has_script = True
        if tag == 'style':
            self.has_style = True

    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()
        else:
            self.errors.append(f'Unexpected closing tag: {tag}')

    def validate(self):
        if self.tags:
            self.errors.append(f'Unclosed tags: {self.tags}')
        return len(self.errors) == 0

with open('index.html', 'r') as f:
    html = f.read()

validator = HTMLValidator()
validator.feed(html)
print('HTML valid:', validator.validate())
if validator.errors:
    for e in validator.errors:
        print('  Error:', e)
print('Has module script:', validator.has_script)
print('Has inline style:', validator.has_style)
print('Total file size:', len(html), 'bytes (', round(len(html)/1024, 1), 'KB)')
